  "หกโมงเช้า เจ็ดโมงก็ไปทำงานแล้ว": "ຫົກໂມງເຊົ້າ ເຈັດໂມງກໍໄປເຮັດວຽກແລ້ວ",
  "งานคุณยุ่งมากใช่ไหม": "ວຽກເຈົ້າຫຍຸ້ງຫຼາຍແມ່ນບໍ",
  "ยุ่งมาก ทำงานวันละ 10 ชั่วโมง เหนื่อยมาก": "ຫຍຸ້ງຫຼາຍ ເຮັດວຽກມື້ລະ 10 ຊົ່ວໂມງ ເມື່ອຍຫຼາຍ",
  "ตอนเย็นคุณมีเวลาไหม": "ຕອນແລງເຈົ້າມີເວລາບໍ",
  "ตอนเย็นฉันอยากพักผ่อนที่บ้าน": "ຕອນແລງຂ້ອຍຢາກພັກຜ່ອນຢູ່ເຮືອນ",
  "ฉันตื่นนอนหกโมงทุกวัน": "ຂ້ອຍຕື່ນນອນຫົກໂມງທຸກມື້",
