  "ฉันคิดว่าว่ายน้ำดีมาก": "ຂ້ອຍຄິດວ່າລອຍນ້ຳດີຫຼາຍ",
  "因为…，所以… = เพราะ...จึง...": "因为…，所以… = ເພາະ...ຈຶ່ງ...",
