  "เพราะฝนตก ฉันจึงไม่ไปวิ่ง": "ເພາະຝົນຕົກ ຂ້ອຍຈຶ່ງບໍ່ໄປແລ່ນ",
  "เพราะเขาป่วย จึงไม่ได้มา": "ເພາະລາວບໍ່ສະບາຍ ຈຶ່ງບໍ່ໄດ້ມາ",
  "没 + กริยา = ไม่ได้... (เรื่องที่ผ่านมา)": "没 + ກິລິຍາ = ບໍ່ໄດ້... (ເລື່ອງທີ່ຜ່ານມາ)",
  "ปฏิเสธเรื่องที่ผ่านมาแล้วใช้ 没 ส่วนเรื่องตอนนี้หรืออนาคตใช้ 不": "ປະຕິເສດເລື່ອງທີ່ຜ່ານມາແລ້ວໃຊ້ 没 ສ່ວນເລື່ອງຕອນນີ້ ຫຼື ອະນາຄົດໃຊ້ 不",
  "เมื่อวานฉันไม่ได้ไปว่ายน้ำ": "ມື້ວານຂ້ອຍບໍ່ໄດ້ໄປລອຍນ້ຳ",
