  "ฉันป่วย กำลังกินยาอยู่": "ຂ້ອຍບໍ່ສະບາຍ ກຳລັງກິນຢາຢູ່",
  "คุณออกกำลังกายทุกวันไหม": "ເຈົ້າອອກກຳລັງກາຍທຸກມື້ບໍ",
  "ฉันชอบวิ่งและว่ายน้ำ แล้วคุณล่ะ": "ຂ້ອຍມັກແລ່ນ ແລະ ລອຍນ້ຳ ແລ້ວເຈົ້າເດ",
  "ฉันชอบเตะฟุตบอล วันนี้อากาศแจ่มใส ไปเตะฟุตบอลกันเถอะ": "ຂ້ອຍມັກເຕະບານ ມື້ນີ້ອາກາດແຈ່ມໃສ ໄປເຕະບານນຳກັນເທາະ",
  "ได้เลย": "ໄດ້ເລີຍ",
  "ฉันชอบวิ่ง": "ຂ້ອຍມັກແລ່ນ",
