  "A + 比 + B + คุณศัพท์ = A ...กว่า B": "A + 比 + B + ຄຸນນາມ = A ...ກວ່າ B",
  "ใช้เปรียบเทียบ ห้ามใส่ 很 หน้าคุณศัพท์": "ໃຊ້ປຽບທຽບ ຫ້າມໃສ່ 很 ໜ້າຄຸນນາມ",
