  "มือถือของฉันใหม่กว่าของคุณ": "ໂທລະສັບຂອງຂ້ອຍໃໝ່ກວ່າຂອງເຈົ້າ",
  "คุณศัพท์ + 的 = อันที่...": "ຄຸນນາມ + 的 = ອັນທີ່...",
