  "ตัวเลขหลักร้อยและหลักพัน": "ຕົວເລກຫຼັກຮ້ອຍ ແລະ ຫຼັກພັນ",
  "百 = ร้อย · 千 = พัน · ถ้ามีศูนย์อยู่ตรงกลาง ต้องพูด 零": "百 = ຮ້ອຍ · 千 = ພັນ · ຖ້າມີສູນຢູ່ກາງ ຕ້ອງເວົ້າ 零",
  "300 หยวน": "300 ຢວນ",
  "สวัสดี มือถือเครื่องนี้ราคาเท่าไร": "ສະບາຍດີ ໂທລະສັບເຄື່ອງນີ້ລາຄາເທົ່າໃດ",
  "2,800 หยวน เครื่องนี้เป็นรุ่นใหม่": "2,800 ຢວນ ເຄື່ອງນີ້ເປັນລຸ້ນໃໝ່",
