  "เครื่องสีขาวนั้น 1,900 ถูกกว่าเครื่องนี้": "ເຄື່ອງສີຂາວນັ້ນ 1,900 ຖືກກວ່າເຄື່ອງນີ້",
  "มีสีดำไหม ฉันไม่ชอบสีขาว": "ມີສີດຳບໍ ຂ້ອຍບໍ່ມັກສີຂາວ",
  "มีครับ เชิญดูก่อน": "ມີເຈົ້າ ເຊີນເບິ່ງກ່ອນ",
  "มีถูกกว่านี้หน่อยไหม": "ມີຖືກກວ່ານີ້ແດ່ບໍ",
  "บอกว่า A อยู่ห่างจาก B ไกลหรือใกล้": "ບອກວ່າ A ຢູ່ຫ່າງຈາກ B ໄກ ຫຼື ໃກ້",
  "สนามบินอยู่ไกลจากที่นี่มาก": "ສະໜາມບິນຢູ່ໄກຈາກບ່ອນນີ້ຫຼາຍ",
  "บ้านฉันอยู่ใกล้โรงเรียน": "ເຮືອນຂ້ອຍຢູ່ໃກ້ໂຮງຮຽນ",
