  "ฉันทำงานตั้งแต่ 8 โมงถึง 5 โมง": "ຂ້ອຍເຮັດວຽກຕັ້ງແຕ່ 8 ໂມງເຖິງ 5 ໂມງ",
  "往 + ทิศทาง + 走 = เดินไปทาง...": "往 + ທິດທາງ + 走 = ຍ່າງໄປທາງ...",
  "ใช้บอกทาง": "ໃຊ້ບອກທາງ",
  "เดินไปทางขวา": "ຍ່າງໄປທາງຂວາ",
  "เดินตรงไป ร้านค้าอยู่ด้านซ้าย": "ຍ່າງຊື່ໄປ ຮ້ານຄ້າຢູ່ເບື້ອງຊ້າຍ",
  "ขอถามหน่อย ไปสนามบินไปทางไหน": "ຂໍຖາມແດ່ ໄປສະໜາມບິນໄປທາງໃດ",
  "สนามบินอยู่ไกลจากที่นี่มาก นั่งรถเมล์ไปเถอะ": "ສະໜາມບິນຢູ່ໄກຈາກບ່ອນນີ້ຫຼາຍ ນັ່ງລົດເມໄປເທາະ",
  "ป้ายรถเมล์อยู่ที่ไหน": "ປ້າຍລົດເມຢູ່ໃສ",
  "เดินตรงไป อยู่ข้างร้านค้า": "ຍ່າງຊື່ໄປ ຢູ່ຂ້າງຮ້ານຄ້າ",
  "จากที่นี่ถึงสนามบินใช้เวลานานเท่าไร": "ຈາກບ່ອນນີ້ເຖິງສະໜາມບິນໃຊ້ເວລາດົນປານໃດ",
  "ใช้เวลา 1 ชั่วโมง": "ໃຊ້ເວລາ 1 ຊົ່ວໂມງ",
  "ไปสนามบินไปทางไหน": "ໄປສະໜາມບິນໄປທາງໃດ",
  "…吧 = ชวน หรือถามยืนยัน": "…吧 = ຊວນ ຫຼື ຖາມຢືນຢັນ",
  "วางท้ายประโยค ใช้ชวนทำด้วยกัน หรือเดาแล้วถามยืนยัน": "ວາງທ້າຍປະໂຫຍກ ໃຊ້ຊວນເຮັດນຳກັນ ຫຼື ເດົາແລ້ວຖາມຢືນຢັນ",
  "ไปกินข้าวด้วยกันเถอะ": "ໄປກິນເຂົ້ານຳກັນເທາະ",
  "คุณเป็นครูใช่ไหม": "ເຈົ້າເປັນອາຈານແມ່ນບໍ",
  "要 + คำนาม / กริยา": "要 + ຄຳນາມ / ກິລິຍາ",
