  "ขอบคุณ ช่วยดูอันนี้ให้หน่อย": "ຂອບໃຈ ຊ່ວຍເບິ່ງອັນນີ້ໃຫ້ແດ່",
  "ได้ อย่าเหนื่อยเกินไปนะ ฝนอาจจะตก กลับบ้านเร็วหน่อยเถอะ": "ໄດ້ ຢ່າເມື່ອຍເກີນໄປເດີ ຝົນອາດຈະຕົກ ກັບເຮືອນໄວແດ່ເທາະ",
  "กริยา + 得 + คุณศัพท์ = ทำ...ได้...": "ກິລິຍາ + 得 + ຄຸນນາມ = ເຮັດ...ໄດ້...",
  "บอกว่าทำได้ดีแค่ไหน เช่น เร็ว ช้า ดี": "ບອກວ່າເຮັດໄດ້ດີປານໃດ ເຊັ່ນ ໄວ ຊ້າ ດີ",
  "เขาวิ่งเร็วมาก": "ລາວແລ່ນໄວຫຼາຍ",
  "คุณพูดภาษาจีนเก่งมาก": "ເຈົ້າເວົ້າພາສາຈີນເກັ່ງຫຼາຍ",
  "ปฏิเสธ: กริยา + 得 + 不 + คุณศัพท์": "ປະຕິເສດ: ກິລິຍາ + 得 + 不 + ຄຸນນາມ",
  "วาง 不 ไว้หลัง 得": "ວາງ 不 ໄວ້ຫຼັງ 得",
  "ฉันเขียนไม่ค่อยดี": "ຂ້ອຍຂຽນບໍ່ຄ່ອຍດີ",
  "เธอร้องเพลงไม่ค่อยเพราะ": "ລາວຮ້ອງເພງບໍ່ຄ່ອຍມ່ວນ",
  "虽然…，但是… = ถึงแม้...แต่...": "虽然…，但是… = ເຖິງແມ່ນ...ແຕ່...",
  "บอกสองเรื่องที่ขัดกัน": "ບອກສອງເລື່ອງທີ່ຂັດກັນ",
  "ถึงจะเหนื่อย แต่ฉันมีความสุข": "ເຖິງຈະເມື່ອຍ ແຕ່ຂ້ອຍມີຄວາມສຸກ",
  "ถึงฝนจะตก แต่เขาก็ยังไปวิ่ง": "ເຖິງຝົນຈະຕົກ ແຕ່ລາວກໍຍັງໄປແລ່ນ",
  "日 กับ 号": "日 ກັບ 号",
  "ทั้งสองคำแปลว่าวันที่ 号 ใช้ในภาษาพูด ส่วน 日 ใช้ในภาษาเขียน": "ທັງສອງຄຳແປວ່າວັນທີ 号 ໃຊ້ໃນພາສາເວົ້າ ສ່ວນ 日 ໃຊ້ໃນພາສາຂຽນ",
  "16 ตุลาคม (ภาษาเขียน)": "16 ຕຸລາ (ພາສາຂຽນ)",
  "16 ตุลาคม (ภาษาพูด)": "16 ຕຸລາ (ພາສາເວົ້າ)",
  "คุณพูดภาษาจีนเก่งจริงๆ": "ເຈົ້າເວົ້າພາສາຈີນເກັ່ງແທ້ໆ",
  "ขอบคุณ ถึงฉันจะพูดได้ดี แต่เขียนไม่ค่อยดี": "ຂອບໃຈ ເຖິງຂ້ອຍຈະເວົ້າໄດ້ດີ ແຕ່ຂຽນບໍ່ຄ່ອຍດີ",
  "คุณเรียนวันละนานเท่าไร": "ເຈົ້າຮຽນມື້ລະດົນປານໃດ",
  "หนึ่งชั่วโมง ถึงจะยุ่ง แต่ฉันก็เรียนทุกวัน": "ໜຶ່ງຊົ່ວໂມງ ເຖິງຈະຫຍຸ້ງ ແຕ່ຂ້ອຍກໍຮຽນທຸກມື້",
  "ถึงจะเหนื่อยแต่มีความสุข": "ເຖິງຈະເມື່ອຍແຕ່ມີຄວາມສຸກ",
  "打算 + กริยา = ตั้งใจจะ...": "打算 + ກິລິຍາ = ຕັ້ງໃຈຈະ...",
