  "สุดสัปดาห์นี้คุณวางแผนจะทำอะไร": "ທ້າຍອາທິດນີ້ເຈົ້າວາງແຜນຈະເຮັດຫຍັງ",
  "ฉันตั้งใจจะไปปีนเขา": "ຂ້ອຍຕັ້ງໃຈຈະໄປປີນພູ",
  "还是 กับ 或者": "还是 ກັບ 或者",
  "还是 ใช้ในคำถามให้เลือก · 或者 ใช้ในประโยคบอกเล่า": "还是 ໃຊ້ໃນຄຳຖາມໃຫ້ເລືອກ · 或者 ໃຊ້ໃນປະໂຫຍກບອກເລົ່າ",
  "คุณจะดื่มชาหรือกาแฟ": "ເຈົ້າຈະດື່ມຊາ ຫຼື ກາເຟ",
  "ฉันจะไปวันเสาร์หรือวันอาทิตย์": "ຂ້ອຍຈະໄປວັນເສົາ ຫຼື ວັນອາທິດ",
  "参加 + กิจกรรม": "参加 + ກິດຈະກຳ",
  "ใช้กับการแข่งขัน การประชุม และงานต่างๆ": "ໃຊ້ກັບການແຂ່ງຂັນ ການປະຊຸມ ແລະ ງານຕ່າງໆ",
  "เขาเข้าร่วมการแข่งขันฟุตบอล": "ລາວເຂົ້າຮ່ວມການແຂ່ງຂັນບານເຕະ",
  "สุดสัปดาห์คุณวางแผนจะทำอะไร": "ທ້າຍອາທິດເຈົ້າວາງແຜນຈະເຮັດຫຍັງ",
  "ฉันตั้งใจไปออกกำลังกายที่สวน หรือไม่ก็ไปปีนเขา": "ຂ້ອຍຕັ້ງໃຈໄປອອກກຳລັງກາຍຢູ່ສວນ ຫຼື ບໍ່ກໍໄປປີນພູ",
  "คุณจะไปวันเสาร์หรือวันอาทิตย์": "ເຈົ້າຈະໄປວັນເສົາ ຫຼື ວັນອາທິດ",
  "วันเสาร์ วันอาทิตย์ฉันต้องไปแข่งบาสเกตบอล": "ວັນເສົາ ວັນອາທິດຂ້ອຍຕ້ອງໄປແຂ່ງບານບ້ວງ",
  "คุณชอบกีฬาจริงๆ": "ເຈົ້າມັກກິລາແທ້ໆ",
  "คุณวางแผนจะทำอะไร": "ເຈົ້າວາງແຜນຈະເຮັດຫຍັງ",
  "有点儿 + คุณศัพท์ = ...นิดหน่อย": "有点儿 + ຄຸນນາມ = ...ໜ້ອຍໜຶ່ງ",
  "มักใช้กับเรื่องที่ไม่ดี หรือไม่พอใจ": "ມັກໃຊ້ກັບເລື່ອງທີ່ບໍ່ດີ ຫຼື ບໍ່ພໍໃຈ",
  "ฉันรู้สึกไม่ค่อยสบาย": "ຂ້ອຍຮູ້ສຶກບໍ່ຄ່ອຍສະບາຍ",
