  "ฉันเชื่อว่าคุณทำได้ดี นี่คือการเลือกเพื่อตัวคุณเอง": "ຂ້ອຍເຊື່ອວ່າເຈົ້າເຮັດໄດ້ດີ ນີ້ແມ່ນການເລືອກເພື່ອຕົວເຈົ້າເອງ",
  "ขอบคุณ ฉันอยากลองดู": "ຂອບໃຈ ຂ້ອຍຢາກລອງເບິ່ງ",
