  "记得 = จำได้ · 不记得 = จำไม่ได้": "记得 = ຈື່ໄດ້ · 不记得 = ຈື່ບໍ່ໄດ້",
  "คุณยังจำฉันได้ไหม": "ເຈົ້າຍັງຈື່ຂ້ອຍໄດ້ບໍ",
  "ฉันจำชื่อเขาไม่ได้แล้ว": "ຂ້ອຍຈື່ຊື່ລາວບໍ່ໄດ້ແລ້ວ",
  "ลักษณนาม 位 / 口 / 段": "ລັກສະນະນາມ 位 / 口 / 段",
