  "向前走 = เดินไปข้างหน้า · 向他学习 = เรียนรู้จากเขา": "向前走 = ຍ່າງໄປທາງໜ້າ · 向他学习 = ຮຽນຮູ້ຈາກລາວ",
  "เดินตรงไปหนึ่งร้อยเมตร": "ຍ່າງຊື່ໄປໜຶ່ງຮ້ອຍແມັດ",
  "พวกเราควรเอาอย่างเขา": "ພວກເຮົາຄວນເອົາແບບຢ່າງລາວ",
  "旧 กับ 老": "旧 ກັບ 老",
  "旧 = เก่า (สิ่งของ) · 老 = แก่ หรือเก่าแก่ (คน, เพื่อน)": "旧 = ເກົ່າ (ສິ່ງຂອງ) · 老 = ເຖົ້າ ຫຼື ເກົ່າແກ່ (ຄົນ, ໝູ່)",
  "มือถือของฉันเก่ามากแล้ว": "ໂທລະສັບຂອງຂ້ອຍເກົ່າຫຼາຍແລ້ວ",
  "เขาเป็นเพื่อนเก่าของฉัน": "ລາວເປັນໝູ່ເກົ່າຂອງຂ້ອຍ",
