  "บ้านท่านอยู่ไม่ไกลจากที่นี่ เดินตรงไปห้าร้อยเมตรก็ถึง": "ເຮືອນທ່ານຢູ່ບໍ່ໄກຈາກບ່ອນນີ້ ຍ່າງຊື່ໄປຫ້າຮ້ອຍແມັດກໍຮອດ",
  "ไม่ได้เจอท่านมาช่วงหนึ่งแล้ว ไปเยี่ยมท่านกันเถอะ": "ບໍ່ໄດ້ພົບທ່ານມາຊ່ວງໜຶ່ງແລ້ວ ໄປຢາມທ່ານນຳກັນເທາະ",
