  "คุณศัพท์ + 地 + กริยา = ทำ...อย่าง...": "ຄຸນນາມ + 地 + ກິລິຍາ = ເຮັດ...ຢ່າງ...",
  "地 อยู่หน้ากริยา บอกวิธีการทำ": "地 ຢູ່ໜ້າກິລິຍາ ບອກວິທີການເຮັດ",
