  "กรุณาพูดช้าๆ": "ກະລຸນາເວົ້າຊ້າໆ",
  "的 / 得 / 地 ต่างกันอย่างไร": "的 / 得 / 地 ຕ່າງກັນແນວໃດ",
  "ทั้งสามอ่านว่า de · 的 + คำนาม (我的书) · กริยา + 得 + คุณศัพท์ (跑得快) · คุณศัพท์ + 地 + กริยา (高兴地笑)": "ທັງສາມອ່ານວ່າ de · 的 + ຄຳນາມ (我的书) · ກິລິຍາ + 得 + ຄຸນນາມ (跑得快) · ຄຸນນາມ + 地 + ກິລິຍາ (高兴地笑)",
  "หนังสือของฉัน": "ປຶ້ມຂອງຂ້ອຍ",
  "เธอยิ้มอย่างดีใจ": "ລາວຍິ້ມຢ່າງດີໃຈ",
  "กริยา + 起来": "ກິລິຍາ + 起来",
  "站起来 = ลุกขึ้น · 看起来 = ดูเหมือนว่า · 想起来 = นึกออก": "站起来 = ລຸກຂຶ້ນ · 看起来 = ເບິ່ງຄືວ່າ · 想起来 = ນຶກອອກ",
  "กรุณาลุกขึ้น": "ກະລຸນາລຸກຂຶ້ນ",
  "คุณดูเหนื่อยมาก": "ເຈົ້າເບິ່ງເມື່ອຍຫຼາຍ",
  "ฉันนึกออกแล้ว": "ຂ້ອຍນຶກອອກແລ້ວ",
  "วางท้ายประโยค ทำให้น้ำเสียงนุ่มลง หรือแสดงความรู้สึก": "ວາງທ້າຍປະໂຫຍກ ເຮັດໃຫ້ນ້ຳສຽງອ່ອນລົງ ຫຼື ສະແດງຄວາມຮູ້ສຶກ",
