  "ผลสอบ HSK 3 ของฉันดีมาก": "ຜົນສອບເສັງ HSK 3 ຂອງຂ້ອຍດີຫຼາຍ",
  "ดีมากเลย คุณตั้งใจเรียนทุกวัน": "ດີຫຼາຍເລີຍ ເຈົ້າຕັ້ງໃຈຮຽນທຸກມື້",
  "ขอบคุณ ครูบอกว่าครั้งหน้าฉันสอบ HSK 4 ได้แล้ว": "ຂອບໃຈ ອາຈານບອກວ່າເທື່ອໜ້າຂ້ອຍສອບ HSK 4 ໄດ້ແລ້ວ",
  "สู้ๆ นะ": "ສູ້ໆເດີ",
