  "ฉันรับผิดชอบเว็บไซต์ของบริษัท": "ຂ້ອຍຮັບຜິດຊອບເວັບໄຊຂອງບໍລິສັດ",
  "คุณต้องรับผิดชอบงานของตัวเอง": "ເຈົ້າຕ້ອງຮັບຜິດຊອບວຽກຂອງຕົວເອງ",
