  "พรุ่งนี้ฉันจะไปธนาคารเป็นเพื่อน เอาเงินส่วนหนึ่งไปฝากไว้": "ມື້ອື່ນຂ້ອຍຈະໄປທະນາຄານເປັນໝູ່ ເອົາເງິນສ່ວນໜຶ່ງໄປຝາກໄວ້",
